/**
 * Shared behaviour between different animal factories
 *
 * @version 1.0
 */
public abstract class AnimalFactory
{

    protected Field field;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Creates an AnimalFactory
     * @param reference to field to later pass in to animals
     */
    public AnimalFactory(Field field) 
    {
        this.field = field;
    }

    /**
     * Creates an Animal given an input animal type
     * @param animalType the type of the animal
     * @param location The base location of the newly created animal
     * @return the created animal
     */
    abstract Animal getAnimal(AnimalType animalType, Location location);

    /**
     * Creates an Animal given an input animal type.
     * @param animalType the type of the animal
     * @param location The base location of the newly created animal
     * @return the created animal
     */
    Animal getAnimal(String animalType, Location location)
    {
        return getAnimal(AnimalType.fromString(animalType), location);
    }
}
/**
 * Producer class for creating Animal factories.
 *
 * @version 1.0
 */
public class AnimalFactoryProducer
{

    /*///////////////////////////////////////////////////////////////
                                STATE
    //////////////////////////////////////////////////////////////*/   

    private Field field;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Creates An animal factory producer.
     * 
     * @param field Reference to field to later pass in to animals.
     */

    public AnimalFactoryProducer(Field field) {
        this.field = field;
    }

    /**
     * Returns a Factory for either herbivore or carnivore animals.
     * 
     * @param isCarnivore Boolean flag to dictate whether to return herbivore or carnivore animal factory.
     */
    public AnimalFactory getFactory(boolean isCarnivore) {
        if(isCarnivore) {
            return new CarnivoreAnimalFactory(field);
        } else {
            return new HerbivoreAnimalFactory(field);
        }
    }
}

/**
 * Factory Class responsible for creating animals that are carnivore.
 *
 * @version 1.0
 */
public class CarnivoreAnimalFactory extends AnimalFactory
{

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Creates a Carnivore Animal Factory.
     * 
     * @param field reference to later pass into animals
     */
    public CarnivoreAnimalFactory(Field field) {
        super(field);
    }

    /**
     * Creates and returns an animal given a particular type.
     * 
     * @param animalType The type of animal to create
     * @param location The initial location of the newly created animal
     * @return the newly created animal
     */
    public Animal getAnimal(AnimalType animalType, Location location) {
        if(animalType == null) {
            return null;
        }
        Gender randomGender = Utils.getRandomEnumValue(Gender.class);
        switch(animalType) {
            case FOX:
                return new CarnivoreFox(true, field, location, randomGender);
            case WOLVERINE:
                return new Wolverine(true, field, location, randomGender);
            case BEAR:
                return new Bear(true, field, location, randomGender);
            default:
                return null;
        }
    }
}
